//! Picture files without FFmpeg, as pictures.read_picture needs no PyAV: a copy whose FFmpeg didn't load, or a build without
//! it, still reads what the picture plugins pick. What cv2.imdecode(IMREAD_COLOR) does to a file is here for both ways of reading one.

use crate::plain_jpeg;
use image::{ImageFormat, ImageReader, Limits};
use std::io::Cursor;
use telescope_core::frame::{Frame, PixelFormat};

/// The most pixels OpenCV reads from one file (CV_IO_MAX_IMAGE_PIXELS).
pub(crate) const MAX_PIXELS: u64 = 1 << 30;

/// The kinds of file the picture plugins take, told apart by their first bytes as cv2.imdecode does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Kind {
    Png,
    Jpeg,
    Webp,
    Bmp,
}

pub(crate) fn kind(bytes: &[u8]) -> Option<Kind> {
    if bytes.starts_with(b"\x89PNG") {
        Some(Kind::Png)
    } else if bytes.starts_with(&[0xff, 0xd8]) {
        Some(Kind::Jpeg)
    } else if bytes.len() > 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some(Kind::Webp)
    } else if bytes.starts_with(b"BM") {
        Some(Kind::Bmp)
    } else {
        None
    }
}

/// The orientation (1..=8) in a TIFF block of EXIF data, 1 when it has none.
fn tiff_orientation(t: &[u8]) -> u8 {
    let big = match t.get(..2) {
        Some(b"MM") => true,
        Some(b"II") => false,
        _ => return 1,
    };
    let u16_at = |at: usize| t.get(at..at + 2).map(|b| if big { u16::from_be_bytes([b[0], b[1]]) } else { u16::from_le_bytes([b[0], b[1]]) });
    let u32_at = |at: usize| t.get(at..at + 4).map(|b| if big { u32::from_be_bytes([b[0], b[1], b[2], b[3]]) } else { u32::from_le_bytes([b[0], b[1], b[2], b[3]]) });
    let Some(ifd) = u32_at(4).map(|v| v as usize) else { return 1 };
    for i in 0..u16_at(ifd).unwrap_or(0) as usize {
        let entry = ifd + 2 + i * 12;
        if u16_at(entry) == Some(0x0112) {
            return u16_at(entry + 8).filter(|v| (1..=8).contains(v)).map_or(1, |v| v as u8);
        }
    }
    1
}

/// The EXIF orientation of a JPEG, PNG or WebP file (cv2.imdecode turns the picture by it), 1 when there is none.
pub fn exif_orientation(bytes: &[u8]) -> u8 {
    if bytes.starts_with(&[0xff, 0xd8]) {
        // Segments up to the picture data: FF, marker, length (counting itself)
        let mut at = 2;
        while let Some(&[0xff, marker, hi, lo]) = bytes.get(at..at + 4) {
            let len = u16::from_be_bytes([hi, lo]) as usize;
            if marker == 0xda || len < 2 {
                break;
            }
            if marker == 0xe1 {
                if let Some(body) = bytes.get(at + 4..at + 2 + len).and_then(|b| b.strip_prefix(b"Exif\0\0")) {
                    return tiff_orientation(body);
                }
            }
            at += 2 + len;
        }
    } else if bytes.starts_with(b"\x89PNG") {
        let mut at = 8;
        while let Some(head) = bytes.get(at..at + 8) {
            let len = u32::from_be_bytes([head[0], head[1], head[2], head[3]]) as usize;
            if &head[4..8] == b"eXIf" {
                return bytes.get(at + 8..at + 8 + len).map_or(1, tiff_orientation);
            }
            if &head[4..8] == b"IDAT" {
                break;
            }
            at += 12 + len;
        }
    } else if bytes.len() > 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        let mut at = 12;
        while let Some(head) = bytes.get(at..at + 8) {
            let len = u32::from_le_bytes([head[4], head[5], head[6], head[7]]) as usize;
            if &head[..4] == b"EXIF" {
                let body = bytes.get(at + 8..at + 8 + len).unwrap_or(&[]);
                return tiff_orientation(body.strip_prefix(b"Exif\0\0").unwrap_or(body));
            }
            at += 8 + len + (len & 1);
        }
    }
    1
}

/// RGBA pixels turned the way EXIF orientation 1..=8 says (mirrored, turned, or both), as cv2.imdecode does after reading a file.
pub(crate) fn oriented(rgba: Vec<u8>, w: usize, h: usize, orientation: u8) -> Frame {
    if orientation <= 1 || orientation > 8 {
        return Frame::new(w as u32, h as u32, PixelFormat::Rgba, rgba);
    }
    let (ow, oh) = if orientation >= 5 { (h, w) } else { (w, h) };
    let mut out = vec![0u8; rgba.len()];
    for oy in 0..oh {
        for ox in 0..ow {
            let (sx, sy) = match orientation {
                2 => (w - 1 - ox, oy),
                3 => (w - 1 - ox, h - 1 - oy),
                4 => (ox, h - 1 - oy),
                5 => (oy, ox),
                6 => (oy, h - 1 - ox),
                7 => (w - 1 - oy, h - 1 - ox),
                _ => (w - 1 - oy, ox),
            };
            out[(oy * ow + ox) * 4..(oy * ow + ox) * 4 + 4].copy_from_slice(&rgba[(sy * w + sx) * 4..(sy * w + sx) * 4 + 4]);
        }
    }
    Frame::new(ow as u32, oh as u32, PixelFormat::Rgba, out)
}

/// A PNG, JPEG, WebP or BMP file as RGBA, turned by its EXIF. Opaque, since IMREAD_COLOR drops alpha without blending it.
pub fn decode(bytes: &[u8]) -> Result<Frame, String> {
    let format = match kind(bytes) {
        Some(Kind::Jpeg) => return plain_jpeg::picture(bytes).ok_or_else(|| "that JPEG can't be read".to_string()),
        Some(Kind::Png) => ImageFormat::Png,
        Some(Kind::Webp) => ImageFormat::WebP,
        Some(Kind::Bmp) => ImageFormat::Bmp,
        None => return Err("not a picture Telescope reads".into()),
    };
    let mut reader = ImageReader::with_format(Cursor::new(bytes), format);
    let mut limits = Limits::default();
    limits.max_alloc = Some(MAX_PIXELS * 4);
    reader.limits(limits);
    let mut rgba = reader.decode().map_err(|e| e.to_string())?.into_rgba8();
    let (w, h) = rgba.dimensions();
    rgba.as_chunks_mut::<4>().0.iter_mut().for_each(|p| p[3] = 255);
    Ok(oriented(rgba.into_raw(), w as usize, h as usize, exif_orientation(bytes)))
}

